@interface TFAIAgentText : UIViewController
@property NSString *initial,*root,*expected,*noteID;
@property BOOL memory;
@property UITextView *text;
@end
@implementation TFAIAgentText
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=UIColor.systemBackgroundColor;self.text=[[UITextView alloc]initWithFrame:self.view.bounds];self.text.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;self.text.font=[UIFont monospacedSystemFontOfSize:14 weight:UIFontWeightRegular];self.text.textContainerInset=UIEdgeInsetsMake(16,12,16,12);self.text.text=self.initial;self.text.editable=self.memory;[self.view addSubview:self.text];if(self.memory)self.navigationItem.rightBarButtonItems=@[AIBar(@"checkmark",@"保存",self,@selector(save)),AIBar(@"square.and.arrow.up",@"导出当前笔记",self,@selector(exportNote))];}
- (void)exportNote{NSString *path=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSUUID.UUID.UUIDString stringByAppendingPathExtension:@"md"]];NSError *error=nil;if(![self.text.text writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:&error]){AIAlert(self,@"导出失败",error.localizedDescription);return;}UIActivityViewController *share=[[UIActivityViewController alloc]initWithActivityItems:@[[NSURL fileURLWithPath:path]] applicationActivities:nil];share.completionWithItemsHandler=^(NSString *type,BOOL done,NSArray *items,NSError *e){[NSFileManager.defaultManager removeItemAtPath:path error:nil];};share.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:share animated:YES completion:nil];}
- (void)save{TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease){AIAlert(self,@"项目正在处理",@"请等待当前文件或Git操作完成后保存。");return;}NSError *error=nil;if(!(self.noteID?[TFAIAgentContext saveNote:self.text.text identifier:self.noteID root:self.root expected:self.expected error:&error]:[TFAIAgentContext saveMemory:self.text.text root:self.root expected:self.expected error:&error])){AIAlert(self,@"记忆未保存",error.localizedDescription);return;}self.expected=[TFAIAgentContext fingerprint:self.text.text];[self.navigationController popViewControllerAnimated:YES];}
@end
@interface TFAIMemoryPage : UITableViewController <UISearchResultsUpdating>
@property NSString *root;
@property NSArray *entries;
@property UISearchController *search;
@end
@implementation TFAIMemoryPage
- (void)viewDidLoad{[super viewDidLoad];self.title=@"本地记忆";self.tableView.accessibilityIdentifier=@"agent-memory-list";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=64;self.search=[[UISearchController alloc]initWithSearchResultsController:nil];self.search.searchResultsUpdater=self;self.search.obscuresBackgroundDuringPresentation=NO;self.search.searchBar.placeholder=@"关键词或日期 YYYY-MM-DD";self.navigationItem.searchController=self.search;self.definesPresentationContext=YES;self.navigationItem.rightBarButtonItem=AIBar(@"square.and.pencil",@"今日笔记",self,@selector(today));}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self updateSearchResultsForSearchController:self.search];}
- (void)updateSearchResultsForSearchController:(UISearchController *)search{self.entries=[TFAIAgentContext memoryEntries:self.root query:search.searchBar.text];[self.tableView reloadData];}
- (void)open:(NSString *)identifier{NSError *error=nil;NSString *text=[TFAIAgentContext readNote:identifier root:self.root error:&error];if(!text){AIAlert(self,@"记忆未打开",error.localizedDescription);return;}TFAIAgentText *page=[TFAIAgentText new];page.title=[identifier isEqual:@"global"]?@"全局 GLOBAL.md":[identifier isEqual:@"project"]?@"项目 MEMORY.md":identifier;page.root=self.root;page.noteID=identifier;page.initial=text;page.expected=[TFAIAgentContext fingerprint:text];page.memory=YES;[self.navigationController pushViewController:page animated:YES];}
- (void)today{NSDateFormatter *format=[NSDateFormatter new];format.locale=[NSLocale localeWithLocaleIdentifier:@"en_US_POSIX"];format.dateFormat=@"yyyy-MM-dd";[self open:[@"daily:" stringByAppendingString:[format stringFromDate:NSDate.date]]];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)section{return self.entries.count;}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)section{return @"笔记只保存在本机，人工编辑并点击保存后生效；AI 按需分页读取，不自动汇集所有项目内容，不自动上传。检索最近366篇每日笔记，列表按修改时间排序。导出前请核对当前内容。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSDictionary *entry=self.entries[i.row];NSString *identifier=entry[@"id"];NSString *name=[identifier isEqual:@"global"]?@"全局笔记":[identifier isEqual:@"project"]?(self.root.length?@"项目笔记":@"通用笔记"):[identifier substringFromIndex:6];NSString *date=[entry[@"modifiedAt"] doubleValue]>0?[NSDateFormatter localizedStringFromDate:[NSDate dateWithTimeIntervalSince1970:[entry[@"modifiedAt"] doubleValue]] dateStyle:NSDateFormatterShortStyle timeStyle:NSDateFormatterShortStyle]:@"尚未保存";UITableViewCell *cell=AICell(name,[NSString stringWithFormat:@"%@ · %@ 字节",date,entry[@"bytes"]],@"brain");cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[self open:self.entries[i.row][@"id"]];}
@end
@interface TFAIAgentSettings : UITableViewController
@property NSString *root,*sessionID;
@property NSArray *skills;
@property(copy) void (^onBrowserAsk)(NSString *url);
@end
@implementation TFAIAgentSettings
- (void)viewDidLoad{[super viewDidLoad];self.title=@"Agent 能力";self.navigationItem.rightBarButtonItem=AIBar(@"switch.2",@"功能开关",self,@selector(toolSettings));self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=70;}
- (void)toolSettings{if(!self.root.length){[self.navigationController pushViewController:TFAIToolRegistrySettingsController() animated:YES];return;}UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"工具设置" message:nil preferredStyle:UIAlertControllerStyleActionSheet];[menu addAction:[UIAlertAction actionWithTitle:@"当前项目工具" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){[self.navigationController pushViewController:TFAIWorkspaceToolSettingsController(self.root) animated:YES];}]];[menu addAction:[UIAlertAction actionWithTitle:@"全局能力开关" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){[self.navigationController pushViewController:TFAIToolRegistrySettingsController() animated:YES];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItem;[self presentViewController:menu animated:YES completion:nil];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.skills=[TFAIAgentContext skills:self.root];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?self.skills.count+(self.root.length?1:0):(s==2?3:2);}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"技能",@"记忆与构建",@"连接与浏览"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return s==0?@"技能正文只在 AI 需要时读取；项目中已有技能不会被覆盖。":s==1?@"记忆保存在本机。关联项目时使用项目 MEMORY.md；未关联时使用通用记忆。":@"浏览器显示真实网页，可将当前页交给 AI；局域网连接用于从 App 直连插件面板的地址与令牌。";}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{NSString *title,*detail,*icon;if(i.section==2&&i.row==2){UITableViewCell *cell=AICell(@"Linux 终端",[TFAIISHRuntime available]?@"Alpine · 当前会话文件与 AI 命令共用":@"当前构建未携带 ARM64 iSH 运行库",@"terminal");cell.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return cell;}if(i.section==0){if(i.row==self.skills.count){title=@"安装技能到当前项目";detail=@"保留已有文件";icon=@"plus.square.on.square";}else{NSDictionary *s=self.skills[i.row];title=s[@"name"];detail=[NSString stringWithFormat:@"%@ · %@",[s[@"source"] isEqual:@"builtin"]?@"内置":@"项目",s[@"description"]];icon=@"text.book.closed";}}else if(i.section==1){title=i.row?@"构建任务":self.root.length?@"项目记忆":@"通用记忆";detail=i.row?@"查看队列和进度":@"编辑 AI 按需读取的本机笔记";icon=i.row?@"hammer":@"brain";}else{title=i.row?@"浏览器":@"局域网连接";detail=i.row?@"浏览网页，并将当前页交给 AI":@"连接 AiFlex2 插件，检测地址与令牌";icon=i.row?@"globe":@"network";}UITableViewCell *c=AICell(title,detail,icon);c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(i.section==2&&i.row==2){[self.navigationController pushViewController:TFAIISHTerminalControllerWithRoot(self.sessionID,self.root) animated:YES];return;}if(i.section==0){if(i.row==self.skills.count){TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease tryWrite];if(!lease){AIAlert(self,@"项目正在处理",@"请稍后安装技能。");return;}NSError *error=nil;if(![TFAIAgentContext installSkills:self.root error:&error])AIAlert(self,@"技能安装未完成",error.localizedDescription);self.skills=[TFAIAgentContext skills:self.root];[t reloadData];return;}NSError *error=nil;NSDictionary *r=[TFAIAgentContext readSkill:self.skills[i.row][@"id"] root:self.root error:&error];if(error){AIAlert(self,@"技能读取失败",error.localizedDescription);return;}TFAIAgentText *page=[TFAIAgentText new];page.title=self.skills[i.row][@"name"];page.initial=r[@"body"];[self.navigationController pushViewController:page animated:YES];return;}if(i.section==1){if(i.row){UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"任务" message:nil preferredStyle:UIAlertControllerStyleActionSheet];[menu addAction:[UIAlertAction actionWithTitle:@"构建队列" style:UIAlertActionStyleDefault handler:^(id a){[self.navigationController pushViewController:TFAIBuildQueueController() animated:YES];}]];[menu addAction:[UIAlertAction actionWithTitle:@"专用子任务" style:UIAlertActionStyleDefault handler:^(id a){[self.navigationController pushViewController:TFAISubtaskController(self.sessionID) animated:YES];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:menu animated:YES completion:nil];return;}TFAIMemoryPage *page=[[TFAIMemoryPage alloc]initWithStyle:UITableViewStyleInsetGrouped];page.root=self.root;[self.navigationController pushViewController:page animated:YES];return;}if(i.row)[self.navigationController pushViewController:TFAIReadOnlyBrowserControllerWithAsk(self.sessionID,self.onBrowserAsk) animated:YES];else{if(i.row==0)[self.navigationController pushViewController:DXLanLinkController() animated:YES];}}
@end
UIViewController *TFAIAgentSettingsControllerWithBrowserAction(NSString *root,NSString *session,void (^onAsk)(NSString *url)){TFAIAgentSettings *p=[[TFAIAgentSettings alloc]initWithStyle:UITableViewStyleInsetGrouped];p.root=root;p.sessionID=session;p.onBrowserAsk=onAsk;return p;}
UIViewController *TFAIAgentSettingsController(NSString *root,NSString *session){return TFAIAgentSettingsControllerWithBrowserAction(root,session,nil);}

